CREATE TABLE #Words (w_nchar NCHAR(5), w_plain CHAR(5));

INSERT INTO #Words VALUES (N'漢字', '漢字');

SELECT
    w_nchar,
    w_plain,
    DATALENGTH(w_nchar) AS nchar_bytes,
    DATALENGTH(w_plain) AS plain_bytes
FROM #Words;
